// @ts-check
import { ConnectionType } from '../ConnectionType.js'
import { IConnectionData } from './IConnectionData.js'

export const DEFAULT_RESPONSE_TIMEOUT_SECONDS = 180

/**
 * @typedef {import('../ConnectionType.js').ConnectionType} ConnectionType
 */

/**
 * Represents WebSocket connection data.
 * @extends IConnectionData
 */
class WsConnectionData extends IConnectionData {
    /**
     * @param {string} hostname - The hostname of the connection.
     * @param {number} [responseTimeoutInSeconds=180] - Response timeout in seconds.
     */
    constructor(hostname, responseTimeoutInSeconds = DEFAULT_RESPONSE_TIMEOUT_SECONDS) {
        super()
        /** @private @type {string} */
        this._hostname = hostname
        /** @private @type {ConnectionType} */
        this._connectionType = ConnectionType.WEB_SOCKET
        /** @private @type {number} */
        this._responseTimeoutInSeconds = responseTimeoutInSeconds
    }

    /** @type {ConnectionType} */
    get connectionType() {
        return this._connectionType
    }

    /** @type {string} */
    get hostname() {
        return this._hostname
    }

    /** @type {string} */
    set hostname(value) {
        this._hostname = value
    }

    /** @type {number} */
    get responseTimeoutInSeconds() {
        return this._responseTimeoutInSeconds
    }

    /**
     * Serializes the connection data.
     * @returns {number[]} An array of connection data values.
     */
    serializeConnectionData() {
        return [this.connectionType, 0, 0, 0, 0, 0, 0]
    }
}

export { WsConnectionData }
